#!/usr/bin/env bash
# Builds the frontend and publishes it, the app config and the demo page to the frontend bucket.
#
#   ./scripts/sync-frontend.sh [env]
#
# env: optional suffix (e.g. dev) naming the stack pair to publish to, as in deploy.sh.
# The browser reads config.js and app.json from its own origin, so the bundle is the same for
# every stack. config.js is generated by deploy.sh for one stack's endpoints; the script refuses
# to publish one that targets another stack's API.
# Hashed bundle files are cached for a year; everything under a stable name is revalidated on
# every visit, then the CloudFront cache is invalidated.
# deploy.sh runs this script as its last step.
# Requires scripts/aws-config.sh (create it with scripts/init-env.sh).
#
#   ./scripts/sync-frontend.sh dev
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# shellcheck source=common.sh
source "$ROOT/scripts/common.sh"

parse_env_suffix_arg "$@"
require_aws_config

CONFIG_JS="$ROOT/frontend/public/config.js"
DEPLOY_CMD="scripts/deploy.sh${1:+ $1}"
BUCKET=$(require_output "$APP" FrontendBucket)
DISTRIBUTION_ID=$(require_output "$APP" DistributionId)
FRONTEND_URL=$(require_output "$APP" FrontendUrl)
TARGET_API_URL=$(require_output "$APP" ApiUrl)

[ -f "$CONFIG_JS" ] \
  || { echo "frontend/public/config.js is missing; run $DEPLOY_CMD to generate it" >&2; exit 1; }
grep -qF "$TARGET_API_URL" "$CONFIG_JS" \
  || { echo "frontend/public/config.js does not target ${APP}'s API ($TARGET_API_URL); run" \
            "$DEPLOY_CMD to regenerate it for this environment" >&2; exit 1; }

(cd "$ROOT/frontend" && npm ci && npm run build)

# app.json and demo.html are not part of the Vite build, so the bulk sync excludes them from
# --delete and they are published on their own.
aws s3 sync "$ROOT/frontend/dist/assets" "s3://${BUCKET}/assets" --delete \
  --cache-control 'public,max-age=31536000,immutable'
aws s3 sync "$ROOT/frontend/dist" "s3://${BUCKET}" --delete --exclude 'assets/*' \
  --exclude app.json --exclude demo.html --cache-control 'no-cache'
aws s3 cp "$ROOT/config/app.json" "s3://${BUCKET}/app.json" --cache-control 'no-cache'
aws s3 cp "$ROOT/docs/demo/demo.html" "s3://${BUCKET}/demo.html" --cache-control 'no-cache'
aws cloudfront create-invalidation --distribution-id "$DISTRIBUTION_ID" --paths '/*' >/dev/null
echo "Frontend synced to ${FRONTEND_URL}"
